doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectBasicCorpSeal', {
    SEAL_TYPE: 'C'
}, function(so) {
    if (so.status == 1) {
        $corpSealList = JSON.parse(so.result[0]);
        if (!Sepoa.request.SMR_NUMBER) {
            isNew = true;
            var smrNumber = getDocumentNumber("SMR"); //채번
            formObj.setValue('SUBJECT', '[인장날인신청] ');
            $(approver_grid_cont).hide();
        } else {
            isNew = false;
            var smrNumber = Sepoa.request.SMR_NUMBER;
        }
        $reqSealInfo.SMR_NUMBER = smrNumber;
        formObj.setValue('SMR_NUMBER', smrNumber);

        var SEAL_C_CategoryCodeArr = [];
        var SEAL_C_CategoryNameArr = [];
        var SEAL_C_NameArr = [];
        var SEAL_C_ManageNumber = [];

        for (var i in $corpSealList) {
            SEAL_C_CategoryCodeArr.push($corpSealList[i].SEAL_CATEGORY);
            SEAL_C_CategoryNameArr.push($corpSealList[i].SEAL_CATEGORY_NAME);
            SEAL_C_NameArr.push($corpSealList[i].SUBJECT);
            SEAL_C_ManageNumber.push($corpSealList[i].MANAGE_NUMBER);
        }

        dataOutput.setValue("SEAL_C_CODE_ARR", SEAL_C_CategoryCodeArr);
        dataOutput.setValue("SEAL_C_NAME_ARR", SEAL_C_CategoryNameArr);
        dataOutput.setValue("SEAL_NAME_ARR", SEAL_C_NameArr);
        dataOutput.setValue("SEAL_NAME_QUANT", SEAL_C_NameArr.length - 1);
        defaultCorpSeal = SEAL_C_ManageNumber;

        formObj.hideItem("byQImpeVRZT");
        if (sUtils.ux.getRootScreenID() == 'SLM_210') {
            initBtn();
            if (!Sepoa.request.SMR_NUMBER) {
                doAddRow();
            }
            let targetBox = "";
            if (Sepoa.request.reflag && Sepoa.request.reflag == 'r') {
                targetBox = "REAL_FLAG";
                callFunction('p', 'setHeaderText', ['실물인감(법인) 날인 예외신청']);
                formObj.setItemLabel("SEAL_EXTRA_INFO", "사유서");
            } else {
                targetBox = "ELECTRON_FLAG";
            }
            formObj.getForm(Object.keys(formObj._formList)[0]).setItemValue(targetBox, 1, false);
            doChange(targetBox, null, 1);

        }
    } else {
        Alert(so.message);
        return;
    }
});


